CREATE TABLE IF NOT EXISTS subcontract_progress_items(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,certificate_id BIGINT UNSIGNED NOT NULL,subcontract_boq_item_id BIGINT UNSIGNED NOT NULL,description_snapshot VARCHAR(1000) NOT NULL,unit_name_snapshot VARCHAR(100) NOT NULL,unit_symbol_snapshot VARCHAR(30) NULL,contract_quantity DECIMAL(18,4) NOT NULL,unit_rate DECIMAL(18,2) NOT NULL,previous_quantity DECIMAL(18,4) NOT NULL DEFAULT 0,current_quantity DECIMAL(18,4) NOT NULL DEFAULT 0,cumulative_quantity DECIMAL(18,4) NOT NULL DEFAULT 0,current_amount DECIMAL(18,2) NOT NULL DEFAULT 0,cumulative_amount DECIMAL(18,2) NOT NULL DEFAULT 0,sort_order INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_subcontract_progress_item(certificate_id,subcontract_boq_item_id),KEY idx_subcontract_progress_item_history(subcontract_boq_item_id,certificate_id),CONSTRAINT fk_subcontract_progress_item_certificate FOREIGN KEY(certificate_id) REFERENCES subcontract_progress_certificates(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_progress_item_boq FOREIGN KEY(subcontract_boq_item_id) REFERENCES subcontract_boq_items(id) ON DELETE RESTRICT,CONSTRAINT chk_subcontract_progress_item_values CHECK(contract_quantity>=0 AND unit_rate>=0 AND previous_quantity>=0 AND current_quantity>=0 AND cumulative_quantity>=0 AND current_amount>=0 AND cumulative_amount>=0 AND cumulative_quantity<=contract_quantity),CONSTRAINT chk_subcontract_progress_item_sort CHECK(sort_order>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
